export function getRegionsWithNearby(regionIds) {
    const result = new Set(regionIds);
    for (const regionId of regionIds) {
        NEARBY_REGIONS[regionId]?.forEach((nearbyId) => result.add(nearbyId));
    }
    return [...result];
}
